import{_ as t,o,c as s,a2 as n}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Mock interview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mock-interview.md","filePath":"guide/mock-interview.md","lastUpdated":1793229750000}'),r={name:"guide/mock-interview.md"};function i(a,e,h,d,l,c){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="mock-interview" tabindex="-1">Mock interview <a class="header-anchor" href="#mock-interview" aria-label="Permalink to &quot;Mock interview&quot;">​</a></h1><p>This page shows how to test MeetCue from start to finish on your own, without hosting or joining a real meeting. MeetCue reads interview questions aloud, listens to your answers through your microphone, and shows talking points in the panel exactly as it would in a meeting. At the end you get a review report.</p><p>Allow about 15 minutes for your first mock interview, including setup.</p><h2 id="three-ways-to-test-on-your-own" tabindex="-1">Three ways to test on your own <a class="header-anchor" href="#three-ways-to-test-on-your-own" aria-label="Permalink to &quot;Three ways to test on your own&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Way</th><th>Needs keys</th><th>Uses your microphone</th><th>What it tests</th></tr></thead><tbody><tr><td><a href="/meetcue/quick-start">Demo replay</a></td><td>No</td><td>No</td><td>How the panel looks and behaves, with a recorded interview</td></tr><tr><td><strong>Mock interview</strong> (this page)</td><td>Yes</td><td>Yes</td><td>The whole app: speech recognition, question detection, hints, coverage ticks, latency and the review</td></tr><tr><td><a href="#meeting-video">Meeting mode with a video</a></td><td>Yes</td><td>Yes</td><td>Meeting mode itself, with a recorded interview standing in for the other side</td></tr></tbody></table><p>Start with the demo if you haven&#39;t set up any keys yet. Use the mock interview for everything else.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ol><li><strong>MeetCue is installed and set up.</strong> You have finished <a href="/meetcue/setup">first-time setup</a>, with a speech recognition key and a model key saved and verified. Without them, the mock interview can read questions but can&#39;t show hints.</li><li><strong>Wear headphones.</strong> In a mock interview, MeetCue plays the questions through your output device and hears them through system sound, exactly as it hears other participants in a meeting. With speakers, your microphone picks the questions up too. MeetCue filters most of that echo, but headphones give the cleanest result.</li><li><strong>Check both level bars.</strong> Open <strong>Settings › Audio</strong>, click <strong>Test levels</strong>, play any video and say something. The microphone bar should move when you speak and the system sound bar when the video plays. If one stays flat, see <a href="/meetcue/troubleshooting/audio">Audio and devices</a>.</li><li><strong>Know the language.</strong> Two built-in samples are in English and two in Chinese. Each language needs a system voice to read the questions; see <a href="#voices">Voices for each language</a>. By default, hints follow the language of the question; you can fix it under <strong>Settings › General › Hint language</strong>.</li></ol><h2 id="step-1" tabindex="-1">Step 1: Open the mock interview window <a class="header-anchor" href="#step-1" aria-label="Permalink to &quot;Step 1: Open the mock interview window {#step-1}&quot;">​</a></h2><p>You can open it from any of these places:</p><ul><li><strong>Tray menu</strong>: click the MeetCue icon in the taskbar notification area and choose <strong>Mock interview…</strong> (third item from the top).</li><li><strong>Panel</strong>: while MeetCue isn&#39;t listening, the panel shows <strong>Try a mock interview</strong> under the start hint.</li><li><strong>Settings › General › Mock interview</strong>: click <strong>Open mock interview</strong>.</li><li><strong>End of setup</strong>: on the last step of the setup window, click <strong>Finish and try a mock interview</strong>.</li></ul><p>The window opens with <strong>How it works</strong> at the top, followed by the sample interviews, your own file, and past practice.</p><p>The window guides you through four steps, shown at the top: <strong>Sound check</strong>, <strong>Questions</strong>, <strong>Review</strong> and <strong>Practise</strong>. Each step ends with a line saying what comes next.</p><h2 id="step-2" tabindex="-1">Step 2: Sound check and the asking voice <a class="header-anchor" href="#step-2" aria-label="Permalink to &quot;Step 2: Sound check and the asking voice {#step-2}&quot;">​</a></h2><p>The first step shows both level bars live. Say something: the microphone bar should move. Play any video, or press <strong>Try it</strong> below: the system sound bar should move. If one stays flat, <strong>Open audio settings</strong> takes you to the device list; see <a href="/meetcue/troubleshooting/audio">Audio and devices</a>.</p><p>Under <strong>The voice that asks the questions</strong>, pick the system voice for each language and press <strong>Try it</strong> to hear a sample sentence. <strong>First available voice</strong> keeps the old behaviour. <strong>Reading speed</strong> is on the same step.</p><h3 id="voices" tabindex="-1">Voices for each language <a class="header-anchor" href="#voices" aria-label="Permalink to &quot;Voices for each language {#voices}&quot;">​</a></h3><p>On macOS, add English or Chinese voices in <strong>System Settings › Accessibility › Spoken Content</strong> (called <strong>Read &amp; Speak</strong> on newer versions), under the system voice picker’s <strong>Manage Voices</strong> option. Reopen the practice window after downloading a voice.</p><p>If Windows has no voice for English or for Chinese, the step says so under that language, with buttons that open the right Windows settings page. To add a voice:</p><ol><li>Click <strong>Open language settings</strong> (Windows Settings › Time &amp; language › Language &amp; region).</li><li>Click <strong>Add a language</strong> and choose <strong>English (United States)</strong> or <strong>中文(简体，中国)</strong>. If the language is already listed, click <strong>…</strong> next to it, then <strong>Language options</strong>.</li><li>Make sure <strong>Text-to-speech</strong> is ticked, then install. Windows downloads the voice in a minute or two.</li><li>Close and reopen the mock interview window. The new voice appears in the list; press <strong>Try it</strong>.</li></ol><p><strong>Open speech settings</strong> (Windows Settings › Time &amp; language › Speech) also has <strong>Add voices</strong>, which installs a voice without changing your display language.</p><h2 id="step-3" tabindex="-1">Step 3: Tell MeetCue about the role (optional) <a class="header-anchor" href="#step-3" aria-label="Permalink to &quot;Step 3: Tell MeetCue about the role (optional) {#step-3}&quot;">​</a></h2><p>Hints are better when MeetCue knows who you are and what the interview is for. This step takes two minutes and is worth doing at least once.</p><ol><li><p>In the sound check step, click <strong>Open briefing material</strong>. It opens <strong>Settings › Hints</strong>.</p></li><li><p>Under <strong>My role</strong>, write one sentence about yourself, for example:</p><ul><li><code>Backend software engineer with 4 years of Go and PostgreSQL</code></li><li><code>Network security engineer moving into AI security, 5 years in a SOC</code></li></ul></li><li><p>Under <strong>Briefing material</strong>, click <strong>Add a file…</strong> and choose a job description. Two samples match the built-in interviews:</p><ul><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-software-engineer.md" target="_blank" rel="noreferrer">jd-software-engineer.md</a>: backend software engineer</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-security-ai.md" target="_blank" rel="noreferrer">jd-security-ai.md</a>: network security engineer on an AI platform team</li></ul><p>Download a sample with the <strong>Download raw file</strong> button on GitHub, or paste a real job description into a <code>.txt</code> or <code>.md</code> file.</p></li></ol><p>See <a href="/meetcue/guide/materials">Briefing material</a> for what is sent and how to keep it focused. Remove the job description afterwards if you don&#39;t want it in your real meetings.</p><h2 id="step-4" tabindex="-1">Step 4: Choose an interview <a class="header-anchor" href="#step-4" aria-label="Permalink to &quot;Step 4: Choose an interview {#step-4}&quot;">​</a></h2><p>Under <strong>Try a sample interview</strong>, click <strong>Use this</strong> next to one of the built-in interviews. You don&#39;t need to download anything.</p><table tabindex="0"><thead><tr><th>Sample</th><th>Language</th><th>Questions</th><th>Topics</th></tr></thead><tbody><tr><td>Software engineer</td><td>English</td><td>14</td><td>Fundamentals, algorithms, system design, debugging, databases, distributed systems and teamwork</td></tr><tr><td>Network security and AI</td><td>English</td><td>12</td><td>TLS, zero trust, lateral movement, DNS exfiltration, ML for intrusion detection, prompt injection, RAG security, AI governance</td></tr><tr><td>Backend software engineer</td><td>Chinese</td><td>14</td><td>Networking, MySQL, Redis, system design, idempotency, troubleshooting, concurrency and teamwork</td></tr><tr><td>Telecom network operations</td><td>Chinese</td><td>42</td><td>Major incidents, home broadband, IP and enterprise lines, optical transport, 5G, data centers and management, in seven groups</td></tr></tbody></table><p>Each sample asks one question at a time, waits for you, and moves on when you pause. Every question has a reference answer, so the review can tell you what you missed. For a long list such as the 42 network operations questions, pick a group or a handful of questions in the next step.</p><p>The same files are in the repository under <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/practice" target="_blank" rel="noreferrer">samples/practice</a>, together with interview transcripts (<code>.srt</code>) you can load with <strong>Choose a file…</strong> to rehearse the flow of a real conversation.</p><p>To use your own questions, click <strong>Choose a file…</strong> under <strong>Use your own file</strong>. See <a href="#own-interview">Write your own interview</a>.</p><h2 id="step-5" tabindex="-1">Step 5: Check the questions <a class="header-anchor" href="#step-5" aria-label="Permalink to &quot;Step 5: Check the questions {#step-5}&quot;">​</a></h2><p>The preview lists every question or line. You can:</p><ul><li>Edit a question&#39;s text by clicking it.</li><li>Move questions up or down, or delete them.</li><li><strong>Filter by text</strong>, or for a question list pick a group under <strong>Show group</strong>, to find questions in a long list.</li><li>Tick several rows to change them at once: <strong>Move to top</strong>, <strong>Move to bottom</strong>, <strong>Keep only these</strong>, <strong>Set group</strong> or <strong>Delete</strong>. Shift-click a second row to tick everything in between; the box in the header ticks every row shown.</li><li>For a question list: <strong>Shuffle</strong>, <strong>Keep the first</strong> few, for example 5 questions for a quick round, or <strong>Add question</strong> to type one of your own.</li><li>For a transcript: check <strong>Which speaker is you?</strong> MeetCue picks the speaker who asks the fewest questions, which is <strong>Candidate</strong> in the samples. Your lines aren&#39;t read aloud; they become the reference answers.</li></ul><p>To practise one group of a long list, choose it under <strong>Show group</strong>, tick the header box, and click <strong>Keep only these</strong>.</p><h2 id="step-6" tabindex="-1">Step 6: Choose how to practise <a class="header-anchor" href="#step-6" aria-label="Permalink to &quot;Step 6: Choose how to practise {#step-6}&quot;">​</a></h2><p>A mock interview works like a real meeting: every question is spoken aloud and comes to MeetCue as sound, and the first two switches decide whether your speech provider transcribes it. Leave both on to test the whole app; turn <strong>Speech-to-text for the questions</strong> off to prepare more cheaply.</p><p>For your first mock interview, use these settings:</p><table tabindex="0"><thead><tr><th>Option</th><th>First run</th><th>Why</th></tr></thead><tbody><tr><td>Speech-to-text for the questions</td><td>On</td><td>The spoken question is captured from system sound and transcribed by your speech provider, exactly like a meeting</td></tr><tr><td>Hint level</td><td><strong>Full</strong></td><td>Shows everything the panel can show</td></tr><tr><td>Pause that ends an answer</td><td>3 seconds</td><td>Raise to 4 or 5 if MeetCue cuts you off while you think</td></tr><tr><td>Follow-up questions</td><td>On</td><td>Tests that MeetCue reacts to what you actually said</td></tr><tr><td>Speech-to-text for my answers</td><td>On</td><td>Needed for coverage ticks and most review figures</td></tr><tr><td>Stop reading when I start speaking</td><td>On</td><td>Lets you interrupt, as in a real conversation</td></tr></tbody></table><p>Then click <strong>Start practice</strong>. The panel comes to the front if it was hidden.</p><h2 id="step-7" tabindex="-1">Step 7: Answer out loud <a class="header-anchor" href="#step-7" aria-label="Permalink to &quot;Step 7: Answer out loud {#step-7}&quot;">​</a></h2><p>For each question, this is what happens:</p><ol><li><strong>MeetCue reads the question</strong> in a Windows voice. The practice window shows <em>Reading the question</em>. Talking with the question still playing stops the reading.</li><li><strong>Hints appear in the panel</strong> about a second and a half after the question ends: the question in grey and three to five numbered talking points, each with a bold keyword.</li><li><strong>You answer out loud</strong>, as if the interviewer were listening. Use the points as cues, not as a script.</li><li><strong>Points tick off</strong> as you cover them, and the next uncovered point is marked <strong>Next</strong>.</li><li><strong>A pause ends your answer.</strong> After the pause you set (3 seconds by default), MeetCue sometimes asks a follow-up, then moves to the next question. If you don&#39;t start within 20 seconds, the panel shows a gentle reminder.</li></ol><p>To go to any other question, use <strong>Go to a question</strong> in the practice window, which lists every question with the current one highlighted, or the question list on the panel&#39;s practice bar. You can jump forwards or back at any time, even while paused. The answer you had given so far is kept for the review; a question you leave without answering counts as skipped.</p><p>The practice window and the panel both show what is expected of you right now, and both have <strong>Ask again</strong>, which reads the current question from the start. Use it when you missed the question or want a second run at the same answer; the answer you had started is discarded and nothing extra is sent to the model.</p><p>MeetCue stops reading when you start to answer, but only for real speech: a cough, an &quot;um&quot; or a word misheard from the question itself doesn&#39;t cut the question short. You can turn interruption off entirely with <strong>Stop reading when I start speaking</strong> in the practice options.</p><p>These shortcuts work while another window has focus:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Enter</code></td><td>I&#39;ve finished answering</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>Skip this question</td></tr><tr><td><code>Ctrl+Alt+Space</code></td><td>Pause or resume</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>Panel: full → mini bar → hidden</td></tr></tbody></table><p>The practice window has the same buttons, plus <strong>End practice</strong>.</p><h2 id="step-8" tabindex="-1">Step 8: Read the review <a class="header-anchor" href="#step-8" aria-label="Permalink to &quot;Step 8: Read the review {#step-8}&quot;">​</a></h2><p>After the last question, or when you click <strong>End practice</strong>, the review opens in its own window. For each question and for the whole session it shows time to start, answer length, coverage, filler words, pace, and three short notes against the reference answer. See <a href="/meetcue/guide/practice#review-report">Review report</a> for what each figure means.</p><p>Click <strong>Export Markdown</strong> to save the report. Past sessions stay under <strong>Past practice</strong> in the mock interview window.</p><h2 id="self-test-plan" tabindex="-1">A complete self-test plan <a class="header-anchor" href="#self-test-plan" aria-label="Permalink to &quot;A complete self-test plan {#self-test-plan}&quot;">​</a></h2><p>Run these five rounds to cover everything MeetCue does, one feature at a time. Each round takes about five minutes.</p><table tabindex="0"><thead><tr><th>Round</th><th>Sample</th><th>Settings</th><th>Check that</th></tr></thead><tbody><tr><td>1</td><td>Software engineer, keep the first 5</td><td>Speech-to-text on, Full</td><td>Each question is read, hints appear, points tick as you speak, the review opens</td></tr><tr><td>2</td><td>Network security and AI, keep the first 5</td><td>Speech-to-text on, Keywords only, with the security job description added</td><td>Hints mention the role (zero trust, detection, LLM security); only keywords show</td></tr><tr><td>3</td><td>Backend software engineer (Chinese), keep the first 5</td><td>Speech-to-text on, Full</td><td>Questions are read in the Chinese voice; hints are in Chinese; <strong>Go to a question</strong> jumps back and forth</td></tr><tr><td>4</td><td>Telecom network operations (Chinese), one group only</td><td>Speech-to-text for the questions off, Delayed (5 s)</td><td>Hints appear about 5 seconds after each question, and the review notes that recognition delay was simulated</td></tr><tr><td>5</td><td>Any question list</td><td>Speech-to-text on, hints Off</td><td>No hints during the round, and you can still answer and get feedback in the review</td></tr></tbody></table><p>After round 1, look at the latency in the panel footer. Around 1.5 seconds is typical; much more points to a slow provider or network. See <a href="/meetcue/troubleshooting/latency">High latency</a>.</p><h2 id="meeting-video" tabindex="-1">Test meeting mode with a video <a class="header-anchor" href="#meeting-video" aria-label="Permalink to &quot;Test meeting mode with a video {#meeting-video}&quot;">​</a></h2><p>A mock interview runs the same pipeline as a meeting, but its pacing is controlled by MeetCue. To test meeting mode itself, let a recording play the interviewer:</p><ol><li>Put on headphones.</li><li>Open a recorded mock interview, for example a technical interview video on YouTube, and pause it at the start.</li><li>Press <code>Ctrl+Alt+Space</code> to start listening. The status dot turns green.</li><li>Play the video. When the interviewer asks a question, a question block with talking points appears.</li><li>Pause the video and answer out loud; watch the points tick off. Resume the video for the next question.</li><li>Press <code>Ctrl+Alt+Space</code> again to stop.</li></ol><p>Anything played through your output device counts as the other side, so this also works with a recorded call or a friend&#39;s question read out by a text-to-speech website.</p><h2 id="own-interview" tabindex="-1">Write your own interview <a class="header-anchor" href="#own-interview" aria-label="Permalink to &quot;Write your own interview {#own-interview}&quot;">​</a></h2><p>The quickest format is a CSV file with a reference answer for each question. Only the <code>question</code> column is required:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>question,reference_answer,category,followups</span></span>
<span class="line"><span>&quot;How does a hash map handle collisions?&quot;,&quot;Chaining or open addressing; resize when the load factor passes a threshold; a good hash function keeps chains short.&quot;,Data structures,&quot;What is the worst-case lookup time?&quot;</span></span>
<span class="line"><span>&quot;How would you detect a compromised API key?&quot;,&quot;Alert on use from new locations or networks, unusual volume or endpoints; rotate keys regularly; scope keys with least privilege.&quot;,Security,</span></span></code></pre></div><p>Separate several follow-ups with <code>|</code>. Question lists can also be plain text or Markdown with one question per line, and transcripts can be <code>.srt</code>, <code>.vtt</code> or <code>.txt</code>. All formats are described in <a href="/meetcue/reference/file-formats">File formats</a>.</p><p>To turn a job description into a question list, you can ask any chat assistant:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Write 12 technical interview questions for the job description below, as a CSV file</span></span>
<span class="line"><span>with the columns question, reference_answer, category and followups. Keep each</span></span>
<span class="line"><span>reference answer to two or three sentences. Separate follow-up questions with |.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;paste the job description&gt;</span></span></code></pre></div><p>Check the questions and answers before you practise with them.</p><h2 id="troubleshooting" tabindex="-1">If something doesn&#39;t work <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;If something doesn&#39;t work {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause and fix</th></tr></thead><tbody><tr><td>The question is read but no hints appear</td><td>A key or model problem. The panel shows an error code; click <strong>See the fix</strong>. Check the key under <strong>Settings › Providers &amp; cost</strong> with <strong>Verify</strong></td></tr><tr><td>No hints with speech-to-text for the questions on, but hints with it off</td><td>MeetCue can&#39;t hear system sound. Check the system sound bar and see <a href="/meetcue/troubleshooting/audio">Audio and devices</a></td></tr><tr><td>Points never tick</td><td><strong>Speech-to-text for my answers</strong> is off, or the microphone bar doesn&#39;t move. Check <strong>Settings › Audio</strong></td></tr><tr><td>Points tick while the question is being read</td><td>The microphone hears the speakers. Use headphones, see <a href="/meetcue/troubleshooting/audio#echo">echo</a></td></tr><tr><td>MeetCue moves on while you&#39;re still thinking</td><td>Raise <strong>Pause that ends an answer</strong> to 4 or 5 seconds</td></tr><tr><td>The voice reads too fast or too slowly</td><td>Change <strong>Reading speed</strong> in the sound check step</td></tr><tr><td>The question stops halfway</td><td>Something in the room interrupts it. Press <strong>Ask again</strong>, use headphones, and if it persists turn off <strong>Stop reading when I start speaking</strong></td></tr><tr><td>The voice is wrong or unpleasant</td><td>Choose another one under <strong>The voice that asks the questions</strong> and press <strong>Try it</strong></td></tr><tr><td>No voices are listed, or none for one language</td><td>Windows has no voice for that language. Follow <a href="#voices">Voices for each language</a></td></tr><tr><td>Hints are generic</td><td>Add <strong>My role</strong> and a job description, see <a href="#step-2">Step 2</a></td></tr></tbody></table><p>With both speech-to-text switches on, a mock interview uses your speech recognition and model providers just like a meeting, and costs about as much as a meeting of the same length. Turning off <strong>Speech-to-text for the questions</strong> skips recognition of the questions; the questions are still spoken aloud. Turning off <strong>Speech-to-text for my answers</strong> as well removes all recognition cost.</p>`,70)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
